// Emberling Plus licensing — an offline, cryptographically signed license
// system (HMAC-SHA256). Keys are generated by the maintainer and validated
// locally; no payment provider is involved (this clone is free — Plus is a
// support/unlock tier that any valid key activates).
const crypto = require("node:crypto");

const SIGNING_SECRET = "8f14e45fceea167a5a36dedd4bea2543-emberling-signing-v1";

function sign(payload) {
  return crypto.createHmac("sha256", SIGNING_SECRET).update(payload).digest("hex").slice(0, 32).toUpperCase();
}

function generateKey(name, signingSecret = SIGNING_SECRET) {
  const id = crypto.randomBytes(4).toString("hex").toUpperCase();
  const payload = `PLUS-${id}-${String(name || "supporter").replace(/[^a-zA-Z0-9]/g, "").slice(0, 16).toUpperCase()}`;
  return `${payload}-${sign(payload, signingSecret)}`;
}

function validate(key) {
  const k = String(key || "").trim().toUpperCase();
  if (!k.startsWith("PLUS-")) return { ok: false, error: "not an Emberling Plus key" };
  const idx = k.lastIndexOf("-");
  if (idx < 0) return { ok: false, error: "malformed key" };
  const payload = k.slice(0, idx);
  const sig = k.slice(idx + 1);
  if (sign(payload) === sig) return { ok: true, name: payload.split("-").slice(2).join(" ") || "supporter" };
  return { ok: false, error: "invalid signature" };
}

module.exports = { generateKey, validate };
